import glob, re, sys
names = set()
for f in glob.glob('_tools/test_*.py') + ['_tools/conftest.py']:
    names |= set(re.findall(r'def (test_\w+)', open(f, encoding='utf-8').read()))
docs = glob.glob('kb/_self/*.md') + glob.glob('.claude/skills/*/SKILL.md') + glob.glob('.claude/agents/*.md') + ['AGENTS.md']
bad = []
for d in docs:
    t = ' '.join(open(d, encoding='utf-8').read().split())
    for m in re.finditer(r'tests? named ((?:`[\w]+`(?:,? (?:and |or )?)?)+)', t):
        for n in re.findall(r'`(\w+)`', m.group(1)):
            if not any(n in x for x in names):
                bad.append((d, n))
print('removed tests the docs still name:', sorted(set(bad)))
sys.exit(1 if bad else 0)
